// Package events is the runtime for code generated by `gwag gen`:
// typed publish / listen calls over a pluggable message bus.
//
// Generated code calls Core; Core encodes messages, fills subjects
// and hands them to a Backend. Backends: events/jetstream (NATS
// JetStream), events/memory (in-process, for tests). Others (Kafka)
// implement Backend. See docs/events.md.
//
// Stability: experimental
package events

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"regexp"
	"time"
)

// Header names on every message.
//
// Stability: experimental
const (
	// HeaderType carries the proto full name of the body message.
	HeaderType = "Gwag-Type"
	// HeaderChannel carries the channel key, "<proto package>.<name>".
	HeaderChannel = "Gwag-Channel"
	// HeaderNatsMsgID carries the message id on NATS (JetStream dedup).
	HeaderNatsMsgID = "Nats-Msg-Id"
	// HeaderMsgID carries the message id on backends other than NATS.
	HeaderMsgID = "Gwag-Msg-Id"
	// HeaderError is added to a dead-lettered message: the last
	// handler error.
	HeaderError = "Gwag-Error"
)

// DLQPrefix starts the subject a message goes to after its last
// failed delivery: DLQPrefix + stream name.
//
// Stability: experimental
const DLQPrefix = "gwag.dlq."

// Channel is one named channel.
//
// Stability: experimental
type Channel struct {
	// Key is "<proto package>.<name>", e.g. "orders.v1.OrderEvents".
	Key string
	// Pattern is the parsed subject pattern.
	Pattern Pattern
	// Stream is the stream (or topic) name: StreamName(Key).
	Stream string
}

// NewChannel validates key and pattern.
//
// Stability: experimental
func NewChannel(key, pattern string) (Channel, error) {
	if key == "" {
		return Channel{}, fmt.Errorf("channel key is empty")
	}
	p, err := ParsePattern(pattern)
	if err != nil {
		return Channel{}, fmt.Errorf("channel %s: %w", key, err)
	}
	return Channel{Key: key, Pattern: p, Stream: StreamName(key)}, nil
}

// MustChannel is NewChannel that panics on error. Generated code uses
// it; `gwag gen` validated the pattern already.
//
// Stability: experimental
func MustChannel(key, pattern string) Channel {
	ch, err := NewChannel(key, pattern)
	if err != nil {
		panic(err)
	}
	return ch
}

// StreamName returns the stream name for a channel key:
// "EV_" + key with "." replaced by "_".
//
// Stability: experimental
func StreamName(key string) string {
	b := []byte("EV_" + key)
	for i := range b {
		if b[i] == '.' {
			b[i] = '_'
		}
	}
	return string(b)
}

// DLQSubject returns the dead-letter subject for a stream.
//
// Stability: experimental
func DLQSubject(stream string) string { return DLQPrefix + stream }

// Message is one message on the wire.
//
// Stability: experimental
type Message struct {
	// Subject is the concrete subject.
	Subject string
	// ID is the message id. The backend carries it in its own header
	// (HeaderNatsMsgID on NATS, HeaderMsgID elsewhere).
	ID string
	// Headers holds HeaderType, HeaderChannel and any extra headers.
	Headers map[string]string
	// Data is the proto binary body.
	Data []byte
	// Delivery is the 1-based delivery attempt. Set on receive.
	Delivery int
}

// Type returns the HeaderType value.
func (m *Message) Type() string { return m.Headers[HeaderType] }

// Handler handles one delivery. nil error acks it; an error asks for
// redelivery.
//
// Stability: experimental
type Handler func(ctx context.Context, m *Message) error

// Backend moves messages. Implementations own delivery: ack on nil
// handler error, redeliver after SubscribeOptions.Delay on error, and
// after MaxDeliver failed deliveries publish the message to
// DLQSubject(ch.Stream) with the original headers plus HeaderError,
// then drop it.
//
// Stability: experimental
type Backend interface {
	// Publish sends m on m.Subject, which matches ch.Pattern.
	Publish(ctx context.Context, ch Channel, m *Message) error
	// Subscribe delivers messages of ch to h. All subscribers with the
	// same group share one queue: each message goes to one of them.
	// Each group gets every message. stop ends this subscriber; the
	// group's position stays.
	Subscribe(ctx context.Context, ch Channel, group string, opts SubscribeOptions, h Handler) (stop func(), err error)
	// Close releases the backend's resources.
	Close() error
}

// Subscription is one (channel, group) a bus listens on. Pass these to
// controlclient's Service.Subscribes.
//
// Stability: experimental
type Subscription struct {
	Channel string
	Group   string
}

// SubscribeOptions is the resolved subscribe configuration a backend
// receives.
//
// Stability: experimental
type SubscribeOptions struct {
	// MaxDeliver is the number of delivery attempts before dead-
	// lettering. Default 5.
	MaxDeliver int
	// DeliverAll starts a new group at the first stored message. The
	// default starts it at new messages.
	DeliverAll bool
	// Backoff is the redelivery delay after failed attempt n
	// (Backoff[n-1], last value repeats). Default 1s, 5s, 30s.
	Backoff []time.Duration
	// AckWait is how long a delivery may run before the backend
	// redelivers it. Default 30s.
	AckWait time.Duration
}

// Delay returns the redelivery delay after failed delivery n (1-based).
func (o SubscribeOptions) Delay(n int) time.Duration {
	if len(o.Backoff) == 0 {
		return 0
	}
	if n < 1 {
		n = 1
	}
	if n > len(o.Backoff) {
		n = len(o.Backoff)
	}
	return o.Backoff[n-1]
}

// SubscribeOption changes SubscribeOptions.
//
// Stability: experimental
type SubscribeOption func(*SubscribeOptions)

// MaxDeliver sets SubscribeOptions.MaxDeliver.
//
// Stability: experimental
func MaxDeliver(n int) SubscribeOption { return func(o *SubscribeOptions) { o.MaxDeliver = n } }

// DeliverAll sets SubscribeOptions.DeliverAll.
//
// Stability: experimental
func DeliverAll() SubscribeOption { return func(o *SubscribeOptions) { o.DeliverAll = true } }

// Backoff sets SubscribeOptions.Backoff.
//
// Stability: experimental
func Backoff(d ...time.Duration) SubscribeOption {
	return func(o *SubscribeOptions) { o.Backoff = append([]time.Duration(nil), d...) }
}

// AckWait sets SubscribeOptions.AckWait.
//
// Stability: experimental
func AckWait(d time.Duration) SubscribeOption { return func(o *SubscribeOptions) { o.AckWait = d } }

// ResolveSubscribeOptions applies opts over the defaults.
//
// Stability: experimental
func ResolveSubscribeOptions(opts ...SubscribeOption) SubscribeOptions {
	o := SubscribeOptions{
		MaxDeliver: 5,
		Backoff:    []time.Duration{time.Second, 5 * time.Second, 30 * time.Second},
		AckWait:    30 * time.Second,
	}
	for _, f := range opts {
		f(&o)
	}
	if o.MaxDeliver < 1 {
		o.MaxDeliver = 1
	}
	return o
}

// PublishOption changes one publish.
//
// Stability: experimental
type PublishOption func(*publishOptions)

type publishOptions struct {
	id      string
	headers map[string]string
}

// MsgID sets the message id. The default is random. Republishing with
// the same id inside the backend's dedup window (JetStream: 2m) stores
// the message once.
//
// Stability: experimental
func MsgID(id string) PublishOption { return func(o *publishOptions) { o.id = id } }

// Header adds a header. HeaderType and HeaderChannel cannot be
// overridden.
//
// Stability: experimental
func Header(key, value string) PublishOption {
	return func(o *publishOptions) {
		if o.headers == nil {
			o.headers = map[string]string{}
		}
		o.headers[key] = value
	}
}

var groupRE = regexp.MustCompile(`^[A-Za-z0-9_-]+$`)

// ValidGroup reports whether group is a usable group name: letters,
// digits, "_" and "-".
//
// Stability: experimental
func ValidGroup(group string) bool { return groupRE.MatchString(group) }

// NewID returns a random message id.
//
// Stability: experimental
func NewID() string {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		panic(err)
	}
	return hex.EncodeToString(b[:])
}

type msgKey struct{}

// MessageFrom returns the message being handled, inside a generated
// handler. nil outside one.
//
// Stability: experimental
func MessageFrom(ctx context.Context) *Message {
	m, _ := ctx.Value(msgKey{}).(*Message)
	return m
}

// WithMessage returns ctx carrying m for MessageFrom. Backends need
// not call it; Core does.
//
// Stability: experimental
func WithMessage(ctx context.Context, m *Message) context.Context {
	return context.WithValue(ctx, msgKey{}, m)
}
